package com.fluxisai.audit;
import java.time.*; import java.util.UUID; import jakarta.persistence.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="audit_events") public class AuditEvent { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="user_id",nullable=false) private UUID userId; @Column(name="event_type",nullable=false,length=30) private String eventType; @Column(name="entity_type",nullable=false,length=60) private String entityType; @Column(name="entity_id") private UUID entityId; @Column(nullable=false,length=30) private String action; @JdbcTypeCode(SqlTypes.JSON) @Column(columnDefinition="jsonb") private String details; @Column(name="created_at",nullable=false) private OffsetDateTime createdAt; protected AuditEvent(){} public AuditEvent(UUID u,String event,String entity,UUID id,String action,String details){userId=u;eventType=event;entityType=entity;entityId=id;this.action=action;this.details=details;createdAt=OffsetDateTime.now(ZoneOffset.UTC);} public UUID getId(){return id;} public String getEventType(){return eventType;} public String getEntityType(){return entityType;} public UUID getEntityId(){return entityId;} public String getAction(){return action;} public String getDetails(){return details;} public OffsetDateTime getCreatedAt(){return createdAt;} }
